CREATE SCHEMA IF NOT EXISTS NLP.MDM;
CREATE TABLE IF NOT EXISTS NLP.MDM.ENTITY (ENTITY_ID VARCHAR(64) PRIMARY KEY, ENTITY_TYPE VARCHAR(64) NOT NULL, CANONICAL_NAME VARCHAR(512) NOT NULL, STATUS VARCHAR(32) DEFAULT 'active', SOURCE_SYSTEM VARCHAR(128), SOURCE_KEY VARCHAR(512), EFFECTIVE_FROM TIMESTAMP_TZ DEFAULT CURRENT_TIMESTAMP(), EFFECTIVE_TO TIMESTAMP_TZ, RECORD_HASH VARCHAR(128), ATTRIBUTES VARIANT);
CREATE TABLE IF NOT EXISTS NLP.MDM.CROSSWALK (CROSSWALK_ID VARCHAR(64) PRIMARY KEY, ENTITY_ID VARCHAR(64) NOT NULL, SYSTEM_CODE VARCHAR(128) NOT NULL, EXTERNAL_KEY VARCHAR(512) NOT NULL, MATCH_METHOD VARCHAR(64) NOT NULL, MATCH_CONFIDENCE NUMBER(6,5), VERIFIED BOOLEAN DEFAULT FALSE, CREATED_AT TIMESTAMP_TZ DEFAULT CURRENT_TIMESTAMP(), UNIQUE(SYSTEM_CODE,EXTERNAL_KEY));
CREATE TABLE IF NOT EXISTS NLP.MDM.PROVENANCE (PROVENANCE_ID VARCHAR(64) PRIMARY KEY, ENTITY_ID VARCHAR(64) NOT NULL, SOURCE_URI VARCHAR(2048), SOURCE_VERSION VARCHAR(128), LICENSE VARCHAR(512), ATTRIBUTION VARCHAR(4096), RETRIEVED_AT TIMESTAMP_TZ DEFAULT CURRENT_TIMESTAMP());
